import json
import urllib.parse

def search_wiki(query):
    url = f"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={urllib.parse.quote(query)}&format=json"
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    try:
        with urllib.request.urlopen(req) as response:
            data = json.loads(response.read().decode())
            return data.get('query', {}).get('search', [])
    except Exception as e:
        print(f"Error searching {query}: {e}")
        return []

def get_page_content(title):
    url = f"https://en.wikipedia.org/w/api.php?action=parse&format=json&page={urllib.parse.quote(title)}&prop=text"
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    try:
        with urllib.request.urlopen(req) as response:
            data = json.loads(response.read().decode())
            return data.get('parse', {}).get('text', {}).get('*', '')
    except Exception as e:
        print(f"Error getting {title}: {e}")
